CREATE TABLE public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text check (char_length(display_name) <= 24), avatar text default 'orange', enabled boolean not null default false);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own ON public.profiles FOR ALL TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.game_saves (user_id uuid primary key, state jsonb not null, updated_at timestamptz not null default now());
GRANT SELECT, INSERT, UPDATE ON public.game_saves TO authenticated;
GRANT ALL ON public.game_saves TO service_role;
ALTER TABLE public.game_saves ENABLE ROW LEVEL SECURITY;
CREATE POLICY saves_own ON public.game_saves FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.expeditions (id uuid primary key default gen_random_uuid(), code text not null unique, owner_id uuid not null, active boolean not null default true, state jsonb not null, revision integer not null default 0, created_at timestamptz not null default now());
GRANT SELECT ON public.expeditions TO authenticated;
GRANT ALL ON public.expeditions TO service_role;
ALTER TABLE public.expeditions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.expedition_members (room_id uuid not null references public.expeditions(id), user_id uuid not null, display_name text not null default 'Explorador', joined_at timestamptz not null default now(), primary key(room_id,user_id));
GRANT SELECT ON public.expedition_members TO authenticated;
GRANT ALL ON public.expedition_members TO service_role;
ALTER TABLE public.expedition_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_expedition_member(r uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.expedition_members WHERE room_id=r AND user_id=auth.uid()); $$;
REVOKE ALL ON FUNCTION public.is_expedition_member(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_expedition_member(uuid) TO authenticated;
CREATE POLICY room_read ON public.expeditions FOR SELECT TO authenticated USING (public.is_expedition_member(id));
CREATE POLICY members_read ON public.expedition_members FOR SELECT TO authenticated USING (public.is_expedition_member(room_id));
CREATE FUNCTION public.create_expedition(initial_state jsonb, explorer_name text) RETURNS public.expeditions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.expeditions; c text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión'; END IF; IF octet_length(initial_state::text)>100000 THEN RAISE EXCEPTION 'Estado demasiado grande'; END IF; LOOP c := upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)); EXIT WHEN NOT EXISTS (SELECT 1 FROM public.expeditions WHERE code=c); END LOOP; INSERT INTO public.expeditions(code,owner_id,state) VALUES(c,auth.uid(),initial_state) RETURNING * INTO r; INSERT INTO public.expedition_members(room_id,user_id,display_name) VALUES(r.id,auth.uid(),left(coalesce(explorer_name,'Explorador'),24)); RETURN r; END $$;
REVOKE ALL ON FUNCTION public.create_expedition(jsonb,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_expedition(jsonb,text) TO authenticated;
CREATE FUNCTION public.join_expedition(room_code text, explorer_name text) RETURNS public.expeditions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.expeditions; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión'; END IF; SELECT * INTO r FROM public.expeditions WHERE code=upper(trim(room_code)) AND active FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'Código inválido o partida cerrada'; END IF; IF NOT EXISTS(SELECT 1 FROM public.expedition_members WHERE room_id=r.id AND user_id=auth.uid()) THEN IF (SELECT count(*) FROM public.expedition_members WHERE room_id=r.id)>=5 THEN RAISE EXCEPTION 'Partida llena: máximo 5 jugadores'; END IF; INSERT INTO public.expedition_members(room_id,user_id,display_name) VALUES(r.id,auth.uid(),left(coalesce(explorer_name,'Explorador'),24)); END IF; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.join_expedition(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.join_expedition(text,text) TO authenticated;
CREATE FUNCTION public.save_expedition(r uuid, next_state jsonb, expected_revision integer) RETURNS public.expeditions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.expeditions; BEGIN IF NOT public.is_expedition_member(r) THEN RAISE EXCEPTION 'No perteneces a esta partida'; END IF; IF octet_length(next_state::text)>100000 THEN RAISE EXCEPTION 'Estado demasiado grande'; END IF; UPDATE public.expeditions SET state=next_state,revision=revision+1 WHERE id=r AND active AND revision=expected_revision RETURNING * INTO result; IF result.id IS NULL THEN RAISE EXCEPTION 'El mundo cambió. Reintenta.'; END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.save_expedition(uuid,jsonb,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_expedition(uuid,jsonb,integer) TO authenticated;
CREATE FUNCTION public.leave_expedition(r uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.expedition_members WHERE room_id=r AND user_id=auth.uid(); END $$;
REVOKE ALL ON FUNCTION public.leave_expedition(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.leave_expedition(uuid) TO authenticated;
CREATE FUNCTION public.close_expedition(r uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.expeditions SET active=false WHERE id=r AND owner_id=auth.uid(); END $$;
REVOKE ALL ON FUNCTION public.close_expedition(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.close_expedition(uuid) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.expeditions;